B.bc6=new A.a0("hamburguesa","Hamburguesa casera con queso y patatas al horno",35,"1 raci\xf3n",B.aKX,B.asP,null,750,37,B.F,B.dF,!1)
B.amu=s(["1-2 tortillas de wrap","120 g de pollo en tiras","1 loncha de queso","2 cucharadas de ma\xedz","\xbc de pepino en tiras","1 cucharadita de aceite, sal y piment\xf3n"],t.s)
