B.awv=s(["Bacalao \u2192 merluza o cualquier pescado blanco."],t.s)
B.ban=new A.aa(B.c5,B.aVL,"Si es congelado, descong\xe9lalo en la nevera la noche antes y s\xe9calo bien.","El bacalao se separa en lascas al tocarlo (8-10 minutos en la salsa).",B.aw5,B.aWR,B.awv,null,null,B.q)
B.atk=s(["Cazuela baja (mejor de barro)","Cazo para las patatas"],t.s)
