B.baB=new A.aa(B.t,B.axm,null,"Pasta al dente y salsa bien caliente; si gratinas, el queso dorado (5 minutos).",B.asN,B.j,B.azL,null,null,B.q)
B.anO=s(["Fuente de horno","Sart\xe9n","Horno"],t.s)
B.apY=s(["Capas: un poco de salsa en el fondo, placas, carne, bechamel\u2026 y termina con bechamel y queso.","D\xe9jala reposar 10 minutos antes de cortar: as\xed no se desmorona."],t.s)
